CREATE TABLE tenants(id uuid PRIMARY KEY, name text NOT NULL, brand_color text NOT NULL DEFAULT '#2563eb');
CREATE TABLE members(id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id), subject text NOT NULL, name text NOT NULL, email text NOT NULL, role text NOT NULL CHECK(role IN ('STUDENT','FACULTY','HOD','ADMIN','RECRUITER','PLATFORM_ADMIN')), department text NOT NULL DEFAULT '', batch text NOT NULL DEFAULT '', registration text NOT NULL DEFAULT '', skills text NOT NULL DEFAULT '', cgpa numeric(4,2), academic_verified boolean NOT NULL DEFAULT false, UNIQUE(tenant_id,subject), UNIQUE(tenant_id,id));
CREATE TABLE problems(id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id), slug text NOT NULL, title text NOT NULL, difficulty text NOT NULL CHECK(difficulty IN ('Easy','Medium','Hard')), topic text NOT NULL, statement text NOT NULL, input_format text NOT NULL, output_format text NOT NULL, constraints_text text NOT NULL, sample_input text NOT NULL, sample_output text NOT NULL, explanation text NOT NULL, published boolean NOT NULL DEFAULT false, version integer NOT NULL DEFAULT 1, UNIQUE(tenant_id,slug), UNIQUE(tenant_id,id));
CREATE TABLE judge_cases(id uuid PRIMARY KEY, tenant_id uuid NOT NULL, problem_id uuid NOT NULL, input text NOT NULL, expected text NOT NULL, FOREIGN KEY(tenant_id,problem_id) REFERENCES problems(tenant_id,id));
CREATE TABLE drafts(tenant_id uuid NOT NULL, member_id uuid NOT NULL, problem_id uuid NOT NULL, language text NOT NULL, source text NOT NULL, version integer NOT NULL DEFAULT 1, updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(tenant_id,member_id,problem_id,language), FOREIGN KEY(tenant_id,member_id) REFERENCES members(tenant_id,id), FOREIGN KEY(tenant_id,problem_id) REFERENCES problems(tenant_id,id));
CREATE TABLE submissions(id uuid PRIMARY KEY, tenant_id uuid NOT NULL, member_id uuid NOT NULL, problem_id uuid NOT NULL, problem_version integer NOT NULL, language text NOT NULL, source text NOT NULL, mode text NOT NULL CHECK(mode IN ('run','submit')), verdict text NOT NULL DEFAULT 'Queued', output text, runtime numeric, idempotency_key text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,member_id,idempotency_key), UNIQUE(tenant_id,id), FOREIGN KEY(tenant_id,member_id) REFERENCES members(tenant_id,id), FOREIGN KEY(tenant_id,problem_id) REFERENCES problems(tenant_id,id));
CREATE TABLE outbox_events(id uuid PRIMARY KEY, tenant_id uuid NOT NULL, submission_id uuid NOT NULL, published boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(tenant_id,submission_id) REFERENCES submissions(tenant_id,id));
CREATE TABLE solved_problems(tenant_id uuid NOT NULL, member_id uuid NOT NULL, problem_id uuid NOT NULL, submission_id uuid NOT NULL, solved_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(tenant_id,member_id,problem_id), FOREIGN KEY(tenant_id,member_id) REFERENCES members(tenant_id,id), FOREIGN KEY(tenant_id,problem_id) REFERENCES problems(tenant_id,id), FOREIGN KEY(tenant_id,submission_id) REFERENCES submissions(tenant_id,id));
CREATE TABLE point_ledger(id uuid PRIMARY KEY, tenant_id uuid NOT NULL, member_id uuid NOT NULL, problem_id uuid NOT NULL, points integer NOT NULL CHECK(points IN (10,20,30)), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,member_id,problem_id), FOREIGN KEY(tenant_id,member_id,problem_id) REFERENCES solved_problems(tenant_id,member_id,problem_id));
CREATE TABLE assessments(id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id), title text NOT NULL, category text NOT NULL, duration_minutes integer NOT NULL CHECK(duration_minutes BETWEEN 1 AND 180), published boolean NOT NULL DEFAULT false, UNIQUE(tenant_id,id));
CREATE TABLE questions(id uuid PRIMARY KEY, tenant_id uuid NOT NULL, assessment_id uuid NOT NULL, prompt text NOT NULL, options jsonb NOT NULL, answer integer NOT NULL CHECK(answer BETWEEN 0 AND 3), explanation text NOT NULL, FOREIGN KEY(tenant_id,assessment_id) REFERENCES assessments(tenant_id,id));
CREATE TABLE attempts(id uuid PRIMARY KEY, tenant_id uuid NOT NULL, member_id uuid NOT NULL, assessment_id uuid NOT NULL, started_at timestamptz NOT NULL DEFAULT now(), deadline timestamptz NOT NULL, finalized boolean NOT NULL DEFAULT false, score integer, total integer, UNIQUE(tenant_id,id), FOREIGN KEY(tenant_id,member_id) REFERENCES members(tenant_id,id), FOREIGN KEY(tenant_id,assessment_id) REFERENCES assessments(tenant_id,id));
CREATE UNIQUE INDEX one_active_attempt ON attempts(tenant_id,member_id,assessment_id) WHERE finalized=false;
CREATE TABLE attempt_answers(tenant_id uuid NOT NULL, attempt_id uuid NOT NULL, question_id uuid NOT NULL REFERENCES questions(id), choice integer CHECK(choice BETWEEN 0 AND 3), marked boolean NOT NULL DEFAULT false, PRIMARY KEY(tenant_id,attempt_id,question_id), FOREIGN KEY(tenant_id,attempt_id) REFERENCES attempts(tenant_id,id));
CREATE TABLE resources(id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id), title text NOT NULL, topic text NOT NULL, type text NOT NULL CHECK(type IN ('Article','Video','Notes')), url text NOT NULL, author_id uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,id), FOREIGN KEY(tenant_id,author_id) REFERENCES members(tenant_id,id));
CREATE TABLE resource_progress(tenant_id uuid NOT NULL, member_id uuid NOT NULL, resource_id uuid NOT NULL, completed boolean NOT NULL DEFAULT false, PRIMARY KEY(tenant_id,member_id,resource_id), FOREIGN KEY(tenant_id,member_id) REFERENCES members(tenant_id,id), FOREIGN KEY(tenant_id,resource_id) REFERENCES resources(tenant_id,id));
CREATE TABLE drives(id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id), company text NOT NULL, title text NOT NULL, location text NOT NULL, salary text NOT NULL, skills text NOT NULL, min_cgpa numeric(4,2) NOT NULL CHECK(min_cgpa BETWEEN 0 AND 10), deadline timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,id));
CREATE TABLE applications(id uuid PRIMARY KEY, tenant_id uuid NOT NULL, member_id uuid NOT NULL, drive_id uuid NOT NULL, status text NOT NULL DEFAULT 'Applied', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,member_id,drive_id), FOREIGN KEY(tenant_id,member_id) REFERENCES members(tenant_id,id), FOREIGN KEY(tenant_id,drive_id) REFERENCES drives(tenant_id,id));
CREATE TABLE notifications(id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id), title text NOT NULL, body text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE ai_reports(id uuid PRIMARY KEY, tenant_id uuid NOT NULL, member_id uuid NOT NULL, kind text NOT NULL, report jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(tenant_id,member_id) REFERENCES members(tenant_id,id));
CREATE TABLE audit_events(id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id), member_id uuid NOT NULL, action text NOT NULL, target text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX submissions_history ON submissions(tenant_id,member_id,created_at DESC);
CREATE INDEX problems_search ON problems(tenant_id,published,topic,difficulty);
CREATE INDEX outbox_pending ON outbox_events(created_at) WHERE published=false;
CREATE INDEX attempts_owner ON attempts(tenant_id,member_id);
CREATE INDEX leaderboard_points ON point_ledger(tenant_id,member_id);
